sys_variable_value.value:
(function execute(inputs, outputs) {
    var utils = new global.AppointmentUtils(inputs.patientId);
    var appoint = utils.getAppointmentsForPatient();

    outputs.appointments = appoint;
    gs.addInfoMessage(`Add info message ${appoint}`);
})(inputs, outputs);

